// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: index < 10 ? 3 : index < 20 ? 4 : 5,
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + ' классы',
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + grade + '.pdf',
      answersUrl: 'assets/medvezhonok/' + year + '/' + grade + '-answers.pdf',
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2022, "2-3", [{"author":"Л. Фёдорова","question":"<em>Сегодня тепло и солнечно, Саша пошёл в школу без</em> _____. Какое слово не изменится, если вставить его в это предложение?","choices":["<em>шапка</em>","<em>куртка</em>","<em>шарф</em>","<em>пальто</em>","<em>свитер.</em>"],"key":"Г","review":["Саша идёт в школу","Подставь слова после «без» и задай вопрос «без чего?». Получатся «без шапки», «без куртки», «без шарфа» и «без свитера».","Сравни «пальто» и «без пальто». Это слово не склоняется, поэтому его форма осталась прежней."]},{"author":"И. Рубанов","question":"В слове <em>медвежонок</em> Игорь обвёл кружочками все буквы, стоящие в русском алфавите на первых шести местах. Сколько кружочков он нарисовал?","choices":["один","два","три","четыре","пять."],"key":"Г","review":["Кружочки Игоря","Назови первые шесть букв алфавита: А, Б, В, Г, Д, Е. Затем пройдись по слову «медвежонок» слева направо.","В слове встретятся Е, Д, В и ещё одна Е. Каждую Е надо обвести отдельно, значит, будет четыре кружочка."]},{"author":"Л. Фёдорова","question":"Лебедь, лиса, свинья. Выберите самый подходящий вариант.","choices":["мех, щетина, пух","щетина, мех, пух","пух, мех, щетина","щетина, пух, мех","пух, щетина, мех."],"key":"В","review":["Покровы животных","Сопоставь животных с тем, что покрывает их тело. У лисы мех, а у свиньи есть жёсткие волоски, которые называют щетиной.","Из предложенных слов лебедю подходит пух. В порядке «лебедь, лиса, свинья» получится «пух, мех, щетина»."]},{"author":"И. Рубанов","question":"Вчера этот день был завтрашним, а сегодня он _____.","choices":["послезавтрашний","завтрашний","сегодняшний","вчерашний","позавчерашний."],"key":"В","review":["Как зовётся этот день","Представь, что вчера была среда. Тогда четверг, который ещё не наступил, назывался завтрашним днём.","Когда четверг наступил, он стал днём, в котором мы находимся. Теперь называем его сегодняшним."]},{"author":"Е. Муравенко","question":"Миша составлял пятибуквенные слова из букв слова <em>парусник</em>. С каким словом он ошибся?","choices":["<em>парус</em>","<em>спина</em>","<em>санки</em>","<em>сурок</em>","<em>парик</em>."],"key":"Г","review":["Слова из «парусника»","Выпиши буквы слова «парусник». В каждом варианте вычёркивай на этом списке буквы, необходимые, чтобы собрать слово.","В слове «сурок» нужна буква О, а в «паруснике» её нет. Для слов «парус», «спина», «санки» и «парик» все нужные буквы есть."]},{"author":"А. Сомин","question":"У какой из этих букв письменная форма сильно отличается от печатной?","choices":["ф","н","с","г","ю."],"key":"Г","review":["Буква от руки","Напиши рядом печатные и строчные рукописные ф, н, с, г, ю. Сравни основные линии каждой пары.","Печатная г выглядит как угол, а рукописная пишется плавной округлой линией. У остальных букв общие очертания узнать легче."]},{"author":"И. Иткин","question":"Сколько слогов в слове <em>вскользь</em>?","choices":["1","2","3","4","8."],"key":"А","review":["Слоги в «вскользь»","Произнеси «вскользь» и найди гласную, на которую приходится голос. Здесь слышится только [о].","На каждый слог приходится один гласный звук. Мягкий знак лишь показывает мягкость согласного, поэтому слог один."]},{"author":"Л. Фёдорова","question":"<em>Гусь гуляет по дорожке.\nГусь играет на гармошке.\nИ гордится гармонист:\n— Я __-__-__-голосист!</em>\nЧто пропущено три раза в последней строчке стихотворения Генриха Сапгира?","choices":["<em>ба</em>","<em>ва</em>","<em>га</em>","<em>да</em>","<em>ква</em>."],"key":"В","review":["Гусь-гармонист","Представь, какой звук мог издать гусь, пока хвастался своим голосом. Послушай, как начинается слово «голосист».","Гусь гогочет «га-га-га». Три «га» перед «голосист» передают его крик, а «ква» подошло бы лягушке."]},{"author":"Е. Муравенко","question":"Найдите лишнее по смыслу.","choices":["<em>ландыш</em>","<em>лютик</em>","<em>цветок</em>","<em>подснежник</em>","<em>одуванчик</em>."],"key":"В","review":["Лишнее среди растений","Назови то, что объединяет ландыш, лютик, подснежник и одуванчик. Все четыре можно назвать цветами.","Проверь, можно ли сказать наоборот: любой цветок — ландыш? Нельзя. «Цветок» — общее название, поэтому оно лишнее в ряду отдельных названий."]},{"author":"Е. Муравенко","question":"В словосочетании <em>бы<strong>стро ка</strong>тится</em> «спрятано» слово <em>строка</em>. В четырёх из данных примеров спрятаны названия посуды, а в одном — название еды. В каком?","choices":["<em>тысяча шкатулок</em>","<em>триста канареек</em>","<em>верблюд целёхонек</em>","<em>доска шахматиста</em>","<em>возьми скатерть</em>."],"key":"Г","review":["Слова на стыке","Соедини конец первого слова с началом второго. Получатся «ча|шка», «ста|кан», «блюд|це», «ка|ша» и «ми|ска».","Чашка, стакан, блюдце и миска — посуда. В выражении «доска шахматиста» на стыке получилось название еды — «каша»."]},{"author":"Н. Лебедева","question":"Сербский язык родствен русскому. Как переводятся на русский язык сербские названия профессий <em>кројач</em>, <em>плесач</em>, <em>возач</em>? (Буква <em>j</em> читается как русская буква <em>й</em>.)","choices":["<em>танцор</em>, <em>водитель</em>, <em>портной</em>","<em>портной</em>, <em>танцор</em>, <em>водитель</em>","<em>водитель</em>, <em>танцор</em>, <em>портной</em>","<em>портной</em>, <em>водитель</em>, <em>танцор</em>","<em>танцор</em>, <em>портной</em>, <em>водитель</em>."],"key":"Б","review":["Профессии по-сербски","Сравни «кројач» с русским «кроить», а «возач» — с «возить». Один работает с тканью, а другой управляет транспортом.","Кроит портной, возит водитель, а «плесач» — танцор. Сохрани порядок сербских слов: портной, танцор, водитель."]},{"author":"О. Подлесская","question":"Догадайтесь, какое слово пропущено в загадке про ромашку:\n<em>Стоит в поле сестричка —\nЖёлтый глазок, белые ________.</em>","choices":["<em>брючки</em>","<em>сапожки</em>","<em>рукавички</em>","<em>реснички</em>","<em>косички</em>."],"key":"Г","review":["Ромашка в загадке","Представь ромашку как лицо: её жёлтая серединка похожа на глаз. Вокруг неё расходятся узкие белые лепестки.","У глаза такие лучики напоминают ресницы. «Реснички» подходит к образу и перекликается по звучанию со словом «сестричка»."]},{"author":"Е. Муравенко","question":"В рассказе Андрея Усачёва «Новый год в зоопарке» упоминается ёжик Вовка, «который знал все магазины в округе как свои сто пятнадцать иголок». А как в таких случаях говорят о людях: <em>знать как свои</em> __________?","choices":["<em>два глаза</em>","<em>тридцать два зуба</em>","<em>пять пальцев</em>","<em>десять пальцев</em>","<em>двадцать пальцев</em>."],"key":"В","review":["Ёжик знает магазины","Ёжик сравнивает своё знание магазинов со знанием собственных иголок. Про людей говорят похожую фразу с частью тела.","В устойчивом выражении «знать как свои пять пальцев» имеется в виду одна рука. Так говорят, когда знают что-то очень хорошо."]},{"author":"Методкомиссия","question":"<em>В пруду плавала семья птиц: селезень, _____ и несколько малышей.</em>\nЗаполните пропуск.","choices":["<em>селезёнка</em>","<em>селезниха</em>","<em>селезня</em>","<em>утка</em>","<em>цесарка</em>."],"key":"Г","review":["Семья в пруду","Определи, кого называют селезнем. Это самец утки, а детёныши у этой птицы — утята.","В семью входят селезень, утка и утята. Значит, на месте пропуска должно стоять «утка»."]},{"author":"И. Иткин","question":"<em>Скинуло кафтан зелёный _____,\nОтсвистели жаворонки всласть.\n_____, в шубу жёлтую одета,\nПо лесам с метёлкою прошлась,\nЧтоб вошла рачительной хозяйкой\nВ снежные лесные терема\nЩеголиха в белой разлетайке —\nРусская румяная _____!</em>\nКакое время года <strong>не</strong> упоминается в этом стихотворении Дмитрия Кедрина?","choices":["весна","лето","осень","зима","в этом стихотворении упоминаются все времена года."],"key":"А","review":["Год в стихотворении","Найди приметы времён года: зелёный кафтан сменяется жёлтой шубой, а потом лес становится снежным.","Заполни пропуски словами «лето», «осень», «зима». Они подходят к приметам и к рифмам «одета» и «терема». Весна в стихотворении не названа."]},{"author":"О. Подлесская","question":"<em>Маша забыла сказать, что нам ещё подарили ________</em> «<em>снегурочки</em>» <em>и мы уже</em> <em>научились кататься.</em> Какое слово пропущено в этой фразе из сказки В. Г. Сутеева?","choices":["<em>ролики</em>","<em>коньки</em>","<em>скейтборды</em>","<em>самокаты</em>","<em>велосипеды</em>."],"key":"Б","review":["Подарок «снегурочки»","Подумай, для какого катания подходит зимнее название «снегурочки». Из перечисленных предметов зимой на льду обычно используют один.","«Снегурочками» называли один из видов коньков. В сказке детям подарили коньки и они научились на них кататься."]},{"author":"И. Рубанов","question":"Учитель спросил у учеников: «Сейчас 15 минут первого. А сколько времени будет через полчаса?». Аня ответила: «12 часов 45 минут». Боря ответил: «Без 15 минут час». Вася ответил: «Без четверти час». Кто из ребят ошибся?","choices":["только Аня","только Боря","только Вася","Боря и Вася","никто."],"key":"Д","review":["Спустя полчаса","«Пятнадцать минут первого» — это 12:15. От этого времени отсчитай ещё 30 минут и получишь 12:45.","От 12:45 до часа остаётся 15 минут, то есть четверть часа. Все трое назвали одно и то же время, поэтому никто не ошибся."]},{"author":"И. Рубанов","question":"В каком порядке надо расположить эти фразы, чтобы получился рассказ?\n1) Поэтому не удивился, когда в феврале мне вручили диплом призёра.\n2) Я записался.\n3) В октябре учительница сказала нам, что скоро будет конкурс «Русский медвежонок».\n4) Все задания, кроме одного, я выполнил верно.","choices":["1, 2, 3, 4","2, 4, 1, 3","3, 2, 1, 4","3, 2, 4, 1","3, 4, 1, 2."],"key":"Г","review":["Как получился диплом","Сначала учительница рассказала о конкурсе (3), затем ученик записался (2). После записи можно было выполнить задания (4).","Слово «поэтому» связывает успешное выполнение задач с получением диплома (1). Порядок фраз — 3, 2, 4, 1."]},{"author":"Л. Фёдорова","question":"Когда все вместе хлопают в ладоши, это называется _____.","choices":["<em>рукобитие</em>","<em>рукоделие</em>","<em>рукопожатия</em>","<em>рукоприкладство</em>","<em>рукоплескания</em>."],"key":"Д","review":["Хлопки в ладоши","Сравни, какие действия называют похожие слова. При рукопожатии пожимают руку, а при рукоделии делают что-нибудь руками.","Плескать руками — старое выражение со значением «хлопать в ладоши». Общие хлопки называют рукоплесканиями."]},{"author":"И. Иткин","question":"Вот обычный порядок нот: <em>до</em>, <em>ре</em>, <em>ми</em>, <em>фа</em>, <em>соль</em>, <em>ля</em>, <em>си</em>.\nРасставим названия нот по алфавиту. Сколько нот останется на своих местах?","choices":["ни одной","1","2","3","4."],"key":"В","review":["Ноты по алфавиту","Расположи ноты по первым буквам. Если первые буквы равны, сравни вторые: «си» пойдёт перед «соль», потому что и раньше о.","Получается «до, ля, ми, ре, си, соль, фа». Только «до» и «ми» остались на первом и третьем местах, значит, таких нот две."]},{"author":"Е. Муравенко","question":"В какой паре второе слово состоит <strong>не</strong> из тех же звуков, что и первое?","choices":["<em>норка — крона</em>","<em>тяпка — пятка</em>","<em>сокол — колос</em>","<em>уклон — кулон</em>","<em>газон — загон</em>."],"key":"Б","review":["Звуки меняют места","Сравни именно звуки: в «тяпке» буква Я смягчает [т’], а [п] перед К остаётся твёрдым. В «пятке» Я смягчает уже [п’], а [т] твёрдый.","Из [т’] и [п] перестановкой нельзя получить [п’] и [т]. В остальных парах порядок меняется, а набор звуков сохраняется."]},{"author":"О. Подлесская","question":"В мультфильме по сказке Валентина Катаева «Цветик-семицветик» девочка Женя говорит: «Ой, сколько ворон со всех сторон! Их тут определённо не меньше ________! Вот я посчитаю… Одна ворона на перилах балкона — раз, ворона вторая на крыше сарая — два». Какое слово пропущено в Жениной фразе?","choices":["ста","пятисот","шестисот","тысячи","миллиона."],"key":"Д","review":["Женя считает ворон","Прочитай реплику вслух. В ней перекликаются «ворон» и «сторон», а чуть дальше — «ворона» и «балкона».","Подставь «миллиона»: оно рифмуется с «ворона» и «балкона». В мультфильме Женя и говорит «не меньше миллиона»."]},{"author":"Л. Фёдорова","question":"Слова <em>яблоко</em> и <em>трава</em> сочетаются с одним и тем же словом <em>зелёный</em>, обозначающим признак: <em>зелёное яблоко</em>, <em>зелёная трава</em>. Для ряда <em>кольцо</em>, <em>осень</em>, <em>ключик</em>, <em>рыбка</em> также есть одно и то же общее слово, обозначающее признак. Какое ещё слово можно добавить к этому ряду?","choices":["<em>зима</em>","<em>руки</em>","<em>вишня</em>","<em>избушка</em>","<em>комар</em>."],"key":"Б","review":["Одно слово для целого ряда","Подбери общий признак для кольца, осени, ключика и рыбки. Все четыре сочетаются со словом «золотой» в нужной форме.","Скажи «золотые руки» про того, кто многое умеет делать. Здесь то же самое прилагательное, поэтому добавить надо «руки»."]},{"author":"И. Иткин","question":"В повести Г. Белых и Л. Пантелеева «Республика ШКИД» рассказывается, как ученики дали учителям сокращённые имена. Какое сокращённое имя образовано с некоторым нарушением общего правила?","choices":["Викниксор (Виктор Николаевич Сорокин)","Эланлюм (Элла Андреевна Люмберг)","Алникпоп (Александр Николаевич Попов)","Косталмед (Константин Александрович Меденников)","все сокращённые имена образованы по общему правилу."],"key":"Г","review":["Сокращённые имена","Раздели прозвища на три части и сравни с именем, отчеством и фамилией. «Вик-ник-сор», «Эл-ан-люм», «Ал-ник-поп» собраны из их начальных букв.","В «Кост-ал-мед» кусочек «Кост» взят из короткого имени «Костя». Полное «Константин» начинается на «Кон», и общее правило здесь нарушено."]},{"author":"О. Подлесская","question":"Закончите последнюю фразу:\n<em>А Анфиса свой рот не открывает. Держит на замке. Тогда папа рот открыл,</em> <em>Вера рот открыла и доктор рот открыл. Такой безмолвный _____ получился.</em> (Э. Успенский)","choices":["<em>хор</em>","<em>цирк</em>","<em>хоровод</em>","<em>карнавал</em>","<em>оркестр</em>."],"key":"А","review":["Открытые рты у доктора","Представь всех, кто открыл рот одновременно. Из предложенных слов только одно обычно обозначает людей, которые так действуют вместе.","Певцы в хоре одновременно открывают рты, чтобы петь. Папа, Вера и доктор молчат, поэтому рассказчик шутит про «безмолвный хор»."]},{"author":"Л. Фёдорова","question":"В сказке Виталия Бианки «Чей нос лучше?» у птиц разнообразные прозвища. Какое из них описывает птичий нос несколько иначе, чем остальные?","choices":["<em>Тонконос</em>","<em>Крестонос</em>","<em>Крючконос</em>","<em>Серпонос</em>","<em>Шилонос</em>."],"key":"А","review":["Птичьи прозвища","Разбери четыре прозвища: Крестонос, Крючконос, Серпонос и Шилонос. В каждом клюв сравнивается с предметом — крестом, крючком, серпом или шилом.","В слове «Тонконос» первая часть «тонко-» описывает толщину клюва. В этом прозвище сравнения с предметом нет."]},{"author":"Е. Туманова","question":"Девочка Маша придумала сказку. В Машином волшебном мире живут: чуткая тучка, солнечный слон, величественный лев, сильный лис, ловкий волк и __________.","choices":["жёлтенький ёжик","быстрая рыба","умная пума","проворная корова","неторопливый енот."],"key":"Д","review":["Машин волшебный мир","Возьми из начала признака столько букв, сколько их в следующем слове. «Чутка» можно переставить в «тучка», «солн» — в «слон», «вел» — в «лев», «сил» — в «лис».","«Ловк» даёт «волк». Так же из первых четырёх букв «неторопливый» получается «енот». В остальных вариантах в начале признака не хватает нужной буквы."]},{"author":"С. Дьяченко","question":"Первокласснице Насте купили компьютерный стул. Однажды Настя собиралась делать уроки и обнаружила, что со стулом кое-что не так. Она возмущённо спросила маму: __________","choices":["Кто обидел мой стул?","Кто оскорбил мой стул?","Кто унизил мой стул?","Кто обругал мой стул?","Кто ущемил мой стул?"],"key":"В","review":["Настин стул","У компьютерного стула можно регулировать высоту сиденья. Представь, что Настя подошла к стулу и увидела, что сиденье стало ниже.","Настя связала слово «унизил» с «низкий», как будто оно означает «сделал ниже». Обычно «унизить» значит оскорбить чьё-то достоинство, и в этом шутка."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
